                bad[k] = f"{frag!r} not in {m['path']}"
                continue
            lines = text.splitlines()
            n = int(m["line"]) if m["line"] else 0
            if not rc.fragment_on_line(lines, n, frag):                     # the WHOLE fragment (review m6)
                bad[k] = f"line {n} of {m['path']} does not hold {frag[:24]!r}"
